-- Golden Gate's glass in Hyprland. Generated by rice-render from palette.toml;
-- hypr.lua loads it on every reload, and `gg glass` sends it again (hyprctl
-- eval) when only the clarity changes. What it draws comes from gg's state,
-- ~/.local/state/goldengate/glass-state.lua:
--   mode     liquid | frosted | solid   (what's on screen: a Liquid that
--                                        failed is already frosted here)
--   backend  hyprglass | hyprliquid | hyprland
--   clarity  0 Ultraclear … 1 Tinted
--   menubar  the menu bar has its background (else it's text on the picture)
-- A clarity change comes with GG_GLASS_LIVE set: no rules then (they'd stack up).

local state_dir = (os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")) .. "/goldengate/"
local ok, s = pcall(dofile, state_dir .. "glass-state.lua")
if not ok or type(s) ~= "table" then s = {} end
local mode    = s.mode or "frosted"
local backend = s.backend or "hyprland"
local c       = math.max(0, math.min(1, tonumber(s.clarity) or 0.35))
local live    = GG_GLASS_LIVE
GG_GLASS_LIVE = nil

local function lerp(a, b) return a + (b - a) * c end
-- "#rrggbb" and an alpha 0–1 as hyprglass's 0xRRGGBBAA
local function rgba(hex, a)
    return tonumber(hex:sub(2, 7) .. string.format("%02x", math.floor(a * 255 + 0.5)), 16)
end
local frost = { light = "{{ light.colors.frost }}", dark = "{{ dark.colors.frost }}" }

-- the shell's surfaces that take the glass, and how its mask finds them
-- (the shell keeps its own shadows under 0.06 while Liquid is on, so a
-- threshold just above them takes only the panels)
local glassed = {
    { "goldengate:dock",          "contour" },
    { "goldengate:controlcenter", "contour" },
    { "goldengate:notifications", "contour" },
    { "goldengate:widgets",       "contour" },
    { "goldengate:spotlight",     "contour" },
    { "goldengate:osd",           "contour" },
    { "goldengate:keys",          "contour" },
}
if s.menubar then table.insert(glassed, { "goldengate:menubar", "alpha" }) end

-- Frosted is Hyprland's blur: wider and grainier as the clarity tints it;
-- Liquid keeps a little of it for what the plugin leaves alone (Launchpad,
-- Mission Control); Solid has none
hl.config({
    decoration = {
        blur = {
            enabled = mode ~= "solid",
            size    = math.floor(lerp(5, 12) + 0.5),
            passes  = c < 0.3 and 3 or 4,
            noise   = lerp(0.006, 0.02),
        },
    },
})

if mode == "liquid" and backend == "hyprglass" and hl.plugin.hyprglass then
    local hg = hl.plugin.hyprglass
    -- Apple's: clear centres, a bright bending rim, a specular top edge.
    -- The shell lays its own tint over the panels, so the plugin's is faint.
    hg.preset("goldengate", {
        inherits = "pomme",
        blur_strength = lerp(0.35, 2.2),
        refraction_strength = lerp(0.8, 0.5),
        refraction_spread = 0.35,
        chromatic_aberration = lerp(0.35, 0.15),
        fresnel_strength = 0.55,
        specular_strength = 0.75,
        edge_thickness_px = 14,
        edge_height = 18,
        noise_strength = lerp(0, 0.06),
        light = { tint_color = rgba(frost.light, lerp(0.02, 0.10)), brightness = 1.08, saturation = 1.15, vibrancy = 0.2 },
        dark  = { tint_color = rgba(frost.dark,  lerp(0.04, 0.16)), brightness = 0.86, saturation = 1.05, vibrancy = 0.15 },
    })
    -- windows: only the see-through ones show it (the terminal, Settings'
    -- sidebar), clearer than panels: frosting where windows stack behind
    hg.preset("goldengate-window", {
        inherits = "goldengate",
        blur_strength = lerp(0.8, 2.6),
        edge_height = 0,
        edge_thickness_px = 10,
        frost = 0.8,
        frost_blur = 2.0,
    })
    hg.config({
        enabled = true,
        default_preset = "goldengate-window",
        layers = { enabled = true, preset = "goldengate", mask_threshold = 0.06, mask_feather = 0.04 },
    })
    if not live then
        for _, l in ipairs(glassed) do
            hg.layer(l[1], { preset = "goldengate", mask_mode = l[2] })
        end
    end
elseif mode == "liquid" and backend == "hyprliquid" and hl.plugin.hyprliquid then
    hl.config({ plugin = { hyprliquid = { watch_system_color_scheme = true, background_sharing = true } } })
    if not live then
        local tint = "rgba(0x80, 0x80, 0x80, " .. string.format("%.2f", lerp(0.02, 0.18)) .. ")"
        for _, l in ipairs(glassed) do
            hl.layer_rule({
                name = "goldengate-liquid-" .. l[1]:gsub("^goldengate:", ""),
                match = { namespace = "^" .. l[1] .. "$" },
                ["hyprliquid:effect"] = "liquid_glass",
                ["hyprliquid:corner_radius"] = l[1] == "goldengate:dock" and 28 or {{ shape.panel }},
                ["hyprliquid:highlight_style"] = 4,
                ["hyprliquid:tint_color"] = tint,
                ["hyprliquid:color_scheme"] = "follow_system",
                ["hyprliquid:vdf_map_mode"] = 1,
                ["hyprliquid:vdf_map_update_policy"] = "onchange",
            })
        end
    end
end
